create role anon;
create role authenticated;
create role service_role;
create schema private;

create sequence public.orders_order_id_seq start with 20;
create sequence public.cart_items_cart_item_id_seq start with 100;

create table public.commodities (
  commodity_id bigint primary key,
  commodity_name text,
  available_quantity numeric,
  price_per_unit numeric default 50,
  farm_id bigint default 1,
  commodity_status text default 'available',
  availability_status text default 'accepting_orders',
  minimum_order_quantity numeric default 1,
  unit_type text default 'kg'
);

create table public.cart_items (
  cart_item_id bigint primary key default nextval('public.cart_items_cart_item_id_seq'),
  commodity_id bigint,
  quantity numeric,
  cart_id bigint,
  price_at_time numeric default 50
);

create table public.orders (
  order_id bigint primary key default nextval('public.orders_order_id_seq'),
  cart_item_id bigint,
  client_order_id text,
  order_status text,
  payment_status text,
  payment_method text,
  total_amount numeric,
  delivery_address text,
  order_date timestamptz,
  created_at timestamptz default now(),
  updated_at timestamptz,
  cancellation_reason text,
  cancelled_by_role text,
  cancelled_at timestamptz,
  stock_reserved_at timestamptz,
  stock_released_at timestamptz,
  buyer_name_snapshot text,
  contact_number text,
  checkout_reference text,
  seller_farm_id bigint default 1,
  delivery_latitude double precision default 14.5995,
  delivery_longitude double precision default 120.9842
);

create table public.users (
  user_id bigint generated by default as identity primary key,
  first_name text, last_name text, contact_number text, email text, account_status text default 'active'
);
create table public.buyers (
  buyer_user_id bigint generated by default as identity primary key,
  user_id bigint, shipping_address text, user_type text default 'Buyer'
);
create table public.carts (
  cart_id bigint generated by default as identity primary key,
  buyer_user_id bigint, cart_status text default 'active'
);
create table public.order_items (
  order_item_id bigint generated by default as identity primary key,
  order_id bigint, quantity numeric, unit_price numeric, total_price numeric
);
create table private.seller_order_registry (
  seller_order_id text primary key, buyer_user_id bigint, seller_farm_id bigint, checkout_reference text
);

create table public.payments (
  payment_id bigint generated by default as identity primary key,
  order_id bigint, amount numeric, payment_method text, transaction_reference text,
  payment_date timestamptz, payment_status text, created_at timestamptz default now(),
  updated_at timestamptz default now(), refund_reference text, refunded_at timestamptz
);
create table public.deliveries (
  delivery_id bigint generated by default as identity primary key,
  order_id bigint, delivery_status text, estimated_delivery_time timestamptz,
  actual_delivery_time timestamptz, pickup_location text, dropoff_location text
);
create table public.riders(rider_id uuid primary key, full_name text, contact_number text);
create table private.rider_delivery_assignments(delivery_id bigint primary key, rider_id uuid);
create table private.order_delivery_fulfillments(delivery_id bigint primary key, pickup_contact text, dropoff_contact text);

